// Lấy tin nhắn từ website + danh sách quà vừa tải, gộp lại để đưa cho AI Agent
const body = $('Webhook').first().json.body || {};
const message = String(body.message || '').trim().slice(0, 500);
const sessionId = String(body.sessionId || 'khach-' + Date.now()).slice(0, 100);
if (!message) throw new Error('Thiếu nội dung tin nhắn');

const products = $input.first().json.products || [];
const fmt = (n) => new Intl.NumberFormat('vi-VN').format(n) + 'đ';
const catalog = products
  .map((p) => [
    'id: ' + p.id,
    p.title,
    'giá: ' + (p.priceLabel || fmt(p.price)),
    'tặng: ' + (p.recipientTypes || []).join(', '),
    'dịp: ' + (p.occasions || []).join(', '),
    'phong cách: ' + (p.vibes || []).join(', '),
    p.insight || '',
  ].join(' | '))
  .map((line) => '- ' + line)
  .join('\n');

return [{ json: { message, sessionId, catalog, validIds: products.map((p) => p.id) } }];

// Đọc JSON mà AI trả về, bỏ các mã sản phẩm không có thật, chuẩn hoá cho website
const raw = String($input.first().json.output || '').trim();
const validIds = new Set($('Chuẩn bị dữ liệu').first().json.validIds || []);

let data = null;
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
if (start !== -1 && end > start) {
  try { data = JSON.parse(raw.slice(start, end + 1)); } catch (e) { data = null; }
}
if (!data || typeof data !== 'object') data = { reply: raw };

const str = (v) => (typeof v === 'string' ? v.trim() : '');
const seen = new Set();
const recommendations = (Array.isArray(data.recommendations) ? data.recommendations : [])
  .map((r) => ({ id: str(r && r.id), reason: str(r && r.reason) }))
  .filter((r) => validIds.has(r.id) && !seen.has(r.id) && seen.add(r.id))
  .slice(0, 4);

return [{
  json: {
    reply: str(data.reply) || 'Xin lỗi, mình chưa hiểu ý bạn. Bạn kể thêm giúp mình: tặng ai, dịp gì, ngân sách bao nhiêu nhé?',
    recommendations,
    followUp: str(data.followUp),
    quickReplies: (Array.isArray(data.quickReplies) ? data.quickReplies : []).map(str).filter(Boolean).slice(0, 4),
  },
}];
